type ReminderMsg = { invoiceId: string; kind: 'due_soon' | 'overdue' };

export async function handleInvoiceReminder(msg: ConsumeMessage) {
  const { invoiceId, kind } = JSON.parse(msg.content.toString()) as ReminderMsg;
  const invoice = await db.invoices.findById(invoiceId);
  if (!invoice || invoice.status === 'paid' || invoice.status === 'void') {
    logger.info({ invoiceId, kind }, 'reminder skipped');
