import { apiGet } from '../src/api';

vi.mock('../src/config', () => ({ loadConfig: async () => ({ baseUrl: 'https://api.example.com', token: 't' }) }));

afterEach(() => vi.unstubAllGlobals());

describe('apiGet retries', () => {
  it('retries 502 then succeeds', async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(new Response('', { status: 502 }))
      .mockResolvedValueOnce(new Response('{"ok":true}'));
    vi.stubGlobal('fetch', fetchMock);
    await expect(apiGet('/v1/ping')).resolves.toEqual({ ok: true });
    expect(fetchMock).toHaveBeenCalledTimes(2);
  });

  it('does not retry 404', async () => {
    const fetchMock = vi.fn().mockResolvedValue(new Response('', { status: 404 }));
    vi.stubGlobal('fetch', fetchMock);
    await expect(apiGet('/v1/nope')).rejects.toThrow('404');
    expect(fetchMock).toHaveBeenCalledTimes(1);
  });
});

