from xml.etree.ElementTree import ParseError

import defusedxml.ElementTree as ET
from django.core.exceptions import ValidationError
from django.core.validators import FileExtensionValidator

MAX_GPX_BYTES = 10 * 1024 * 1024
GPX_NAMESPACES = {"http://www.topografix.com/GPX/1/1", "http://www.topografix.com/GPX/1/0"}

gpx_extension = FileExtensionValidator(allowed_extensions=["gpx"])


def validate_gpx(upload):
    if upload.size > MAX_GPX_BYTES:
        raise ValidationError("GPX files must be under 10 MB.")
    upload.seek(0)
    try:
        root = ET.parse(upload).getroot()
    except ParseError as exc:
        raise ValidationError("This file is not valid XML.") from exc
    finally:
        upload.seek(0)
    ns, _, tag = root.tag.rpartition("}")
    if tag != "gpx" or ns.lstrip("{") not in GPX_NAMESPACES:
        raise ValidationError("This file is not a GPX track.")
    if not root.findall(".//{*}trkpt") and not root.findall(".//{*}rtept"):
        raise ValidationError("This GPX file has no track or route points.")

