import { readFileSync } from "node:fs";
import { parse } from "csv-parse/sync";

type Row = { number: string; client: string; status: string; total_cents: string; currency: string };

const file = process.argv[2];
if (!file) {
  console.error("usage: tsx scripts/invoice-status-summary.ts <export.csv>");
  process.exit(1);
}

const rows: Row[] = parse(readFileSync(file), { columns: true, skip_empty_lines: true });
const summary = new Map<string, { count: number; totals: Map<string, number> }>();

for (const r of rows) {
  const s = summary.get(r.status) ?? { count: 0, totals: new Map() };
  s.count += 1;
  s.totals.set(r.currency, (s.totals.get(r.currency) ?? 0) + Number(r.total_cents));
  summary.set(r.status, s);
}

for (const [status, { count, totals }] of [...summary].sort((a, b) => b[1].count - a[1].count)) {
  const money = [...totals].map(([c, cents]) => `${(cents / 100).toFixed(2)} ${c}`).join(", ");
  console.log(`${status.padEnd(8)} ${String(count).padStart(5)}  ${money}`);
}

