/** 100 requests per minute per client IP, counted in Redis so all API replicas share the budget. */
export default fp<{ redis: Redis }>(async (app, opts) => {
  await app.register(rateLimit, {
    max: 100,
    timeWindow: '1 minute',
    redis: opts.redis,
    nameSpace: 'rl:public:',
    keyGenerator: (req) => req.ip,
    allowList: (req) => req.url === '/healthz',
  });
});

