import { createHmac } from 'node:crypto';

export const SIGNATURE_HEADER = 'X-Acme-Signature';

/** Signs the raw JSON body of an outgoing webhook: hex HMAC SHA-256 with the endpoint secret. */
export function sign(body: string, secret: string, timestamp: number): string {
  const mac = createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
  return `t=${timestamp},v1=${mac}`;
}

