import { useMemo, useState } from 'react'
import { ArrowDown, ArrowUp } from 'lucide-react'
import { useInvoices } from '@/hooks/use-invoices'
import { Button } from '@/components/ui/button'
import { Table, TableBody, TableHead, TableHeader, TableRow } from '@/components/ui/table'
import { InvoiceRow } from './invoice-row'

type SortDir = 'asc' | 'desc'

export function InvoicesTable() {
  const { data, isLoading } = useInvoices()
  const [dir, setDir] = useState<SortDir>('asc')

  const rows = useMemo(() => {
    if (!data) return []
    const sign = dir === 'asc' ? 1 : -1
    return [...data].sort((a, b) => sign * (Date.parse(a.dueDate) - Date.parse(b.dueDate)))
  }, [data, dir])

  if (isLoading || !data) return null
  return (
    <Table>
      <TableHeader>
        <TableRow>
          <TableHead>Number</TableHead>
          <TableHead>Client</TableHead>
          <TableHead>
            <Button
              variant="ghost"
              size="sm"
              aria-label={`Sort by due date ${dir === 'asc' ? 'descending' : 'ascending'}`}
              onClick={() => setDir(dir === 'asc' ? 'desc' : 'asc')}
            >
              Due {dir === 'asc' ? <ArrowUp className="size-3" /> : <ArrowDown className="size-3" />}
            </Button>
          </TableHead>
          <TableHead className="text-right">Total</TableHead>
        </TableRow>
      </TableHeader>
      <TableBody>
        {rows.map((inv) => <InvoiceRow key={inv.id} invoice={inv} />)}
      </TableBody>
    </Table>
  )
}

