import { describe, expect, it } from 'vitest'
import { formatMoney } from './money'

describe('formatMoney', () => {
  it('rounds half up on the decimal value', () => {
    expect(formatMoney(2.005, 'CAD')).toBe('$2.01')
    expect(formatMoney(1.005, 'USD', 'en-US')).toBe('$1.01')
  })

  it('formats credit notes as negative amounts', () => {
    expect(formatMoney(-12.5, 'CAD')).toBe('-$12.50')
    expect(formatMoney(-0.004, 'CAD')).toBe('-$0.00')
  })

  it('keeps whole amounts unchanged', () => {
    expect(formatMoney(1200, 'EUR', 'en-CA')).toBe('€1,200.00')
  })

  it('uses the locale separators', () => {
    expect(formatMoney(1234.5, 'EUR', 'fr-CA')).toBe('1 234,50 €')
  })
})

