import { and, eq, isNull } from 'drizzle-orm';
import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import { db } from '../../db/client.js';
import { customers } from '../../db/schema.js';
import { problem } from '../../lib/problem.js';

const Params = z.object({ id: z.string().uuid() });

export const deleteCustomerRoute: FastifyPluginAsync = async (app) => {
  app.delete('/v1/customers/:id', async (req, reply) => {
    const parsed = Params.safeParse(req.params);
    if (!parsed.success) {
      return problem(reply, 400, 'Invalid customer id');
    }
    const orgId = req.auth.orgId;
    const [row] = await db
      .update(customers)
      .set({ deletedAt: new Date() })
      .where(and(eq(customers.id, parsed.data.id), eq(customers.orgId, orgId), isNull(customers.deletedAt)))
      .returning({ id: customers.id });
    if (!row) {
      return problem(reply, 404, 'Customer not found');
    }
    return reply.code(204).send();
  });
};

