export interface LineInput {
  quantity: number;
  unitPriceCents: number;
  taxRate: number; // e.g. 0.13
  discountPct?: number;
}

export function computeTotals(lines: LineInput[]) {
  let subtotal = 0;
  let tax = 0;
  for (const l of lines) {
    const net = l.quantity * l.unitPriceCents * (1 - (l.discountPct ?? 0) / 100);
    subtotal += net;
    tax += net * l.taxRate;
  }
  return {
    subtotalCents: Math.round(subtotal),
    taxCents: Math.round(tax),
    totalCents: Math.round(subtotal + tax),
  };
}

