'use server';

import { revalidatePath } from 'next/cache';
import { apiFetch } from '@/lib/api';

export interface CompanyFormState {
  error?: string;
  ok?: boolean;
}

export async function saveCompany(_prev: CompanyFormState, form: FormData): Promise<CompanyFormState> {
  const name = String(form.get('name') ?? '').trim();
  const taxId = String(form.get('taxId') ?? '').trim();
  const senderEmail = String(form.get('senderEmail') ?? '').trim();
  if (!name || !senderEmail) {
    return { error: 'Company name and sender email are required.' };
  }
  const res = await apiFetch('/v1/org/profile', {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ name, taxId: taxId || null, senderEmail }),
  });
  if (!res.ok) return { error: 'Could not save company profile.' };
  revalidatePath('/settings/company');
  return { ok: true };
}

