'use client';

import { useActionState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { saveCompany, type CompanyFormState } from './actions';

interface Props {
  initial: { name: string; taxId: string | null; senderEmail: string };
}

export function CompanyForm({ initial }: Props) {
  const [state, action, pending] = useActionState<CompanyFormState, FormData>(saveCompany, {});

  return (
    <form action={action} className="max-w-md space-y-4">
      <div className="space-y-1">
        <Label htmlFor="name">Company name</Label>
        <Input id="name" name="name" defaultValue={initial.name} required />
      </div>
      <div className="space-y-1">
        <Label htmlFor="taxId">Tax ID</Label>
        <Input id="taxId" name="taxId" defaultValue={initial.taxId ?? ''} />
      </div>
      <div className="space-y-1">
        <Label htmlFor="senderEmail">Send invoices from</Label>
        <Input id="senderEmail" name="senderEmail" type="email" defaultValue={initial.senderEmail} required />
      </div>
      {state.error ? <p className="text-sm text-destructive">{state.error}</p> : null}
      {state.ok ? <p className="text-sm text-muted-foreground">Saved.</p> : null}
      <Button type="submit" disabled={pending}>
        {pending ? 'Saving...' : 'Save'}
      </Button>
    </form>
  );
}

