export function truncate(text: string, max: number): string {
  if (text.length <= max) return text;
  const cut = text.slice(0, max - 1);
  const lastSpace = cut.lastIndexOf(' ');
  const base = lastSpace > 0 ? cut.slice(0, lastSpace) : cut;
  return `${base.trimEnd()}\u2026`;
}
```
Short strings come back unchanged; longer ones are cut at the last space that fits, with a single-character ellipsis so the result never exceeds `max`. A single long word gets a hard cut. Four tests in `lib/text.test.ts`, all passing.

