import type { Job } from 'bullmq';
import { and, eq, isNull, lt } from 'drizzle-orm';
import { db } from '../db';
import { invoices, orgs } from '../db/schema';
import { sendReminderEmail } from '../email';

export async function overdueReminders(job: Job) {
  const now = new Date();
  const allOrgs = await db.select().from(orgs).where(isNull(orgs.deletedAt));

  for (const org of allOrgs) {
    if (!org.remindersEnabled) continue;
    if (org.plan === 'free' && org.reminderCountThisMonth >= 20) continue;

    const overdue = await db
      .select()
      .from(invoices)
      .where(and(eq(invoices.orgId, org.id), eq(invoices.status, 'open'), lt(invoices.dueAt, now)));

    if (overdue.length === 0) continue;

    for (const inv of overdue) {
      await sendReminderEmail(org, inv);
    }
  }
}

