import type { FastifyPluginAsync } from 'fastify';
import { and, desc, eq, isNull, lt } from 'drizzle-orm';
import { z } from 'zod';
import { db } from '../db/client';
import { clients } from '../db/schema';

const listQuery = z.object({
  cursor: z.string().uuid().optional(),
  limit: z.coerce.number().int().min(1).max(100).default(25),
});

export const clientRoutes: FastifyPluginAsync = async (app) => {
  app.get('/v1/clients', async (req) => {
    const { cursor, limit } = listQuery.parse(req.query);
    const rows = await db
      .select()
      .from(clients)
      .where(and(eq(clients.orgId, req.auth.orgId), isNull(clients.deletedAt), cursor ? lt(clients.id, cursor) : undefined))
      .orderBy(desc(clients.id))
      .limit(limit + 1);
    const hasMore = rows.length > limit;
    return { data: rows.slice(0, limit), nextCursor: hasMore ? rows[limit - 1]?.id : null };
  });
};

