import { describe, expect, it } from 'vitest';
import { buildApp, seedClients } from '../test/helpers';

describe('GET /v1/clients?q=', () => {
  it('matches on email', async () => {
    const { app, auth } = await buildApp();
    await seedClients(auth.orgId, [{ name: 'Ada', email: 'ada@studio.example.com' }, { name: 'Bob', email: 'bob@x.example.com' }]);
    const res = await app.inject({ url: '/v1/clients?q=studio', headers: auth.headers });
    expect(res.json().data.map((c: { name: string }) => c.name)).toEqual(['Ada']);
  });

  it('treats % as a literal', async () => {
    const { app, auth } = await buildApp();
    await seedClients(auth.orgId, [{ name: '100% Design' }, { name: 'Other' }]);
    const res = await app.inject({ url: '/v1/clients?q=%25', headers: auth.headers });
    expect(res.json().data).toHaveLength(1);
  });

  it('combines q with the cursor', async () => {
    const { app, auth } = await buildApp();
    await seedClients(auth.orgId, Array.from({ length: 5 }, (_, i) => ({ name: `Studio ${i}` })));
    const first = await app.inject({ url: '/v1/clients?q=studio&limit=2', headers: auth.headers });
    const next = await app.inject({ url: `/v1/clients?q=studio&limit=2&cursor=${first.json().nextCursor}`, headers: auth.headers });
    expect(next.json().data).toHaveLength(2);
  });
});

