import { handleStripeEvent } from "../../billing/stripe-events.js";

const stripe = new Stripe(env.STRIPE_SECRET_KEY, { timeout: 10_000 });

export const stripeWebhookRoutes: FastifyPluginAsync = async (app) => {
  app.post("/v1/webhooks/stripe", { config: { public: true } }, async (req, reply) => {
    const sig = req.headers["stripe-signature"];
    let event: Stripe.Event;
    try {
