      req.log.warn({ err: String(err) }, "stripe signature verification failed");
      return reply.code(400).send({ type: "about:blank", title: "Invalid signature", status: 400 });
    }
    await handleStripeEvent(event);
    return reply.code(200).send({ received: true });
  });
};

