import type Stripe from "stripe";
import { markInvoicePaid, markInvoiceFinalized, recordRefund, syncCustomer } from "./sync.js";
import { logger } from "../logger.js";

export async function handleStripeEvent(event: Stripe.Event): Promise<void> {
  switch (event.type) {
    case "invoice.paid":
      await markInvoicePaid(event.data.object as Stripe.Invoice);
      break;
    case "invoice.finalized":
      await markInvoiceFinalized(event.data.object as Stripe.Invoice);
      break;
    case "charge.refunded":
      await recordRefund(event.data.object as Stripe.Charge);
      break;
    case "customer.updated":
      await syncCustomer(event.data.object as Stripe.Customer);
      break;
    default:
      logger.debug({ type: event.type }, "unhandled stripe event");
  }
}

