import { useEffect, useState } from "react";
import { formatDueDate, relativeFromNow } from "@/lib/format-date";

export function DueDate({ iso }: { iso: string }) {
  // The server renders in UTC and the browser in local time; formatting only after mount keeps both renders equal.
  const [label, setLabel] = useState<string | null>(null);

  useEffect(() => {
    setLabel(`${formatDueDate(iso)} (${relativeFromNow(iso)})`);
  }, [iso]);

  return (
    <time dateTime={iso} className="text-sm text-muted-foreground">
      {label ?? iso.slice(0, 10)}
    </time>
  );
}

