export function ResendButton({ invoiceId }: { invoiceId: string }) {
  const [pending, startTransition] = useTransition();

  function onClick() {
    startTransition(async () => {
      const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/v1/invoices/${invoiceId}/resend`, {
        method: "POST",
      });
      if (res.ok) toast.success("Invoice sent again");
      else toast.error("Could not resend the invoice");
    });
  }

  return (
    <Button variant="outline" onClick={onClick} disabled={pending}>
      <Send className="mr-2 size-4" />
      {pending ? "Sending..." : "Resend"}
    </Button>
  );
}

